reg('lightpath4','Reflection and Refraction','반사와 굴절','S4P1.b–c',(i,lv)=>{const angle=[10,20,30,40,50,15,25,35,45,55][i],reflect=i<5;if(lv===1)return q(B('Which process is described?','설명한 빛의 과정을 골라요.'),B(reflect?`A ray arriving at ${angle}° to the normal bounces from a flat mirror.`:`A ray at a slant crosses air into water and bends. Entry angle: ${angle}° to the normal.`,reflect?`표면에 수직인 선(법선)과 ${angle}°를 이루는 빛이 평평한 거울에서 되돌아와요.`:`빛이 공기에서 물로 비스듬히 들어가 꺾여요. 표면에 수직인 선(법선)과 들어오는 빛이 이루는 입사각은 ${angle}°예요.`),b(reflect?'Reflection|반사':'Refraction|굴절'),[b(reflect?'Refraction|굴절':'Reflection|반사'),b('Absorption|흡수')]);if(reflect)return q(B('Angles are measured from the normal. Find the reflected angle.','각은 표면에 수직인 법선에서 재요. 반사각을 골라요.'),B(`Flat mirror model: incoming angle ${angle}°.`,`평평한 거울 모형: 입사각 ${angle}°.`),`${angle}°`,[`${90-angle}°`,`${angle+5}°`]);return q(B('A pencil looks bent at the air-water boundary. Which explanation fits?','연필이 공기와 물의 경계에서 꺾여 보여요. 까닭을 골라요.'),B(`Practice view ${i-4}: pencil enters water at ${angle}°. Its position is unchanged.`,`연습 관찰 ${i-4}: 연필이 ${angle}°로 물에 들어 있어요. 실제 위치는 바뀌지 않았어요.`),b('Light changes direction across the boundary|경계에서 빛의 방향이 바뀌어요'),[b('The pencil must physically break|연필이 실제로 부러져야 해요'),b('Light travels straight with no change at the boundary|경계에서 방향 변화 없이 빛이 곧게 나아가요')]);});
reg('vibration4','Vibration and Sound','떨림과 소리','S4P2.a',(i,lv)=>{const freq=100+i*25,amp=1+i%3,faster=i%2===0,afterFreq=faster?freq*2:freq,afterAmp=faster?amp:amp*2;return q(B(lv===1?'Only the shown feature changes. What sound property changes?':'Compare both properties, using the silent data.',lv===1?'표시된 특성만 변해요. 어떤 소리 성질이 변할까요?':'무음 자료로 소리의 두 성질을 비교해요.'),B(`Practice data: before ${freq} vibrations/s, amplitude ${amp}; after ${lv===2?afterFreq*2:afterFreq}, amplitude ${afterAmp}. Same medium.`,`가상 자료: 전에는 초당 진동 ${freq}회, 진폭 ${amp}; 뒤에는 ${lv===2?afterFreq*2:afterFreq}회, 진폭 ${afterAmp}. 매질은 같아요.`),b(lv===1?(faster?'Higher pitch, similar loudness|더 높은 소리, 비슷한 크기':'Louder sound, same pitch|더 큰 소리, 같은 높이'):(faster?'Higher pitch, similar loudness|더 높은 소리, 비슷한 크기':'Higher pitch and louder sound|더 높고 더 큰 소리')),[b('No change in pitch or loudness|높이와 크기가 모두 같아요'),b('Lower pitch and quieter sound|더 낮고 더 작은 소리')]);});
