 return q(B(lv===1?'Identify the simple machine.':'What change of force or movement can this ideal device provide?',lv===1?'간단한 기계의 이름을 골라요.':'이상적인 도구가 힘이나 움직임을 어떻게 바꿀까요?'),lv===1?B(`Practice device ${i+1}. ${r[1].en}`,`연습 도구 ${i+1}. ${r[1].ko}`):B(`${context.en} ${r[1].en}`,`${context.ko} ${r[1].ko}`),lv===1?r[0]:r[2],lv===1?[b(machines[(j+1)%6][0]),b(machines[(j+2)%6][0])]:[b('It removes the need for all work|필요한 일을 모두 없애요'),b('It always creates free energy|언제나 에너지를 공짜로 만들어요')]);
